\begin{quadro}[htbp]
    \centering
    \caption{Comparação entre sistemas relacionados e a plataforma proposta}
    \label{qua:relacionados}
    \begin{tabularx}{\textwidth}{|p{2.6cm}|p{3.2cm}|X|X|}
        \hline
        \textbf{Sistema} & \textbf{Escopo} & \textbf{Características relatadas} & \textbf{Diferença em relação à proposta} \\
        \hline
        Herbário Virtual Reflora \cite{forzza2015reflora} & Imagens e dados de exsicatas de herbários nacionais e estrangeiros & Alta resolução; consulta pública; mais de um milhão de imagens em 2015 & Escala nacional e internacional; não gerencia o livro de tombo nem a rotina de curadoria do herbário do IFPI \\ \hline
        Jabot \cite{silva2019agrupamentos} & Gerenciamento de coleções do Jardim Botânico do Rio de Janeiro & PHP e PostgreSQL; PostGIS para validação geográfica; cerca de 760 mil registros & Sistema institucional de grande porte; a proposta é uma plataforma enxuta, voltada a um herbário didático \\ \hline
        Symbiota \cite{gries2014symbiota} & Plataforma web para comunidades de dados de biodiversidade & Baseada em espécimes-testemunho; recursos de troca de dados & Plataforma genérica e configurável; a proposta é desenvolvida sob medida para o acervo do campus \\ \hline
        INCT-HVFF e \textit{speciesLink} \cite{incthvff2026} & Rede nacional de dados de herbários brasileiros e de coletas depositadas no exterior & Dados livres, abertos e integrados; repatriamento de dados; Herbário Virtual via \textit{speciesLink} & Integra dezenas de instituições; a proposta atende a um único herbário e à sua rotina de cadastro \\ \hline
        Herbário Virtual Glaziou \cite{glaziou2026} & Exsicatas coletadas por Glaziou, de dois museus & Informações e imagens das exsicatas; usa a rede \textit{speciesLink} & Acervo histórico e temático; a proposta cobre todo o acervo do herbário do campus \\ \hline
        Herbario Digital (Chile) \cite{herbariodigital2026} & Flora vascular do Chile & Catálogo taxonômico, busca de imagens, espécimes e mapa & Foco em outro país; serve de referência de organização da consulta \\ \hline
    \end{tabularx}
    \fonte{Elaborado pelo autor, com base nas páginas e nos autores citados.}
\end{quadro}
